        value: 7,
    };
    println!("entry: {} -> {}", entry.key, entry.value);
    let found: Maybe<char> = Maybe::Just('x');
    let missing: Maybe<char> = Maybe::Nothing;
    println!("maybe: {found:?} and {missing:?}");
}

